// Legacy helpers. game.js now uses its own puzzleIndexForNumber() (66-cycle before the
// 2026-10-12 cutover, new puzzles in order after it). These mirror that mapping so any caller stays consistent.
function totalCrossIndexForNumber(n) {
  const LEGACY = 66, CUTOVER_N = 158; // 2026-10-12
  if (n < CUTOVER_N) return (Math.max(1, n) - 1) % LEGACY % PUZZLES.length;
  return (LEGACY + (n - CUTOVER_N)) % PUZZLES.length;
}

function getTodaysPuzzle() {
  const now = new Date();
  now.setHours(0, 0, 0, 0);
  const launch = new Date('2026-05-08T00:00:00');
  const day = Math.max(0, Math.floor((now - launch) / 86400000));
  return PUZZLES[totalCrossIndexForNumber(day + 1)];
}

function getPuzzleByIndex(i) {
  return PUZZLES[totalCrossIndexForNumber(i + 1)];
}
